"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[3010],{54716:i=>{i.exports=JSON.parse('{"tag":{"label":"Visualizer","permalink":"/datagol-knowlegde-base-v1/docs/tags/visualizer","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":37,"items":[{"id":"BI Analytics/Drill Down/Drill Down","title":"About Drill-Down","description":"Drill-down is a powerful data exploration technique that allows you to move from a high-level summary to more detailed views. By clicking on a data point within a dashboard or report\u2014such as a bar, metric, or chart segment\u2014you can reveal deeper layers of information. This enables you to quickly investigate trends, spot anomalies, and understand performance breakdowns without leaving your current view.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/"},{"id":"BI Analytics/Visualizer/About Visualizer","title":"About Visualizer","description":"The Visualizer is a crucial component for performing Business Intelligence (BI) Analytics. It\'s where you actively engage in data visualization to transform raw data into actionable insights, ultimately driving data-driven decision-making.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/about-visualizer"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Widget Configuration and Settings","title":"About widget configuration and settings","description":"DataGOL offers a flexible way to visualize your data through configurable widgets.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/Widget Configuration and Settings"},{"id":"BI Analytics/Visualizer/Aggregate functions","title":"Aggregate functions","description":"Aggregate functions are calculations performed on a set of values to produce a single summary value. They are incredibly useful for gaining insights from large datasets by condensing information into meaningful metrics. In effect you are prompting the Visualizer to take a numerical column, perform a specific calculation (Sum, Max, Min, Average, Count, Unique Count etc.) on its values, and then display the results grouped by the categories in this other column.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/aggregate-functions"},{"id":"BI Analytics/Alerts","title":"Alerts","description":"Alerting is a core feature in DataGOL that allows you to create alerts and notifications in DataGOL for tracking key performance indicators (KPIs) effectively.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Alerts"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Area chart widget","title":"Area chart widget","description":"Configuring Area chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/area-chart-widget-configuration-settings"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Bar chart widget","title":"Bar chart widget","description":"Configuring Bar chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/bar-chart-widget-configuration-settings"},{"id":"BI Analytics/Formulas & Parameters/BI Formula","title":"BI Formulas","description":"What Are Formulas in DataGOL?","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Formulas & Parameters/BI Formula"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Box plot widget","title":"Box plot widget","description":"Configuring Box plot widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/box-plot-widget-configuration-settings"},{"id":"BI Analytics/Column Aggregation","title":"Column Aggregations","description":"In DataGOL, users can apply various aggregation types to columns to summarize and analyze data effectively. These aggregations help transform raw values into meaningful insights \u2014 such as totals, averages, trends, and patterns.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Column Aggregation"},{"id":"BI Analytics/Conditional Formatting","title":"Conditional Formatting","description":"Conditional formatting allows you to visually highlight and analyze your data by applying specific rules. You can enhance data analysis with the conditional formatting feature for tables and pivot tables. This powerful tool allows you to define custom rules to dynamically color-code cells based on their values. It provides a strong reasoning for its use by enabling quick visual identification of key data points that meet specific thresholds or criteria, which is a far more efficient method of data comprehension than manual inspection.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/conditional-format"},{"id":"BI Analytics/Visualizer/Creating visualization or widget","title":"Creating visualization or widget","description":"1.  Select a workbook to visualize data. You can choose one of the following types of workbooks:","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/create-visualization-or-create-widget"},{"id":"BI Analytics/Dashboards/Dashboards","title":"Dashboards","description":"Dashboards are interactive visual interfaces that consolidate and present key data points in a clear, accessible format. They enable users to monitor performance, uncover trends, and make informed decisions by visualizing complex datasets through charts, tables, and key performance indicators (KPIs).","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Dashboards/"},{"id":"BI Analytics/Visualizer/Dashboards","title":"Dashboards","description":"Dashboards are interactive visual interfaces that consolidate and present key data points in a clear, accessible format. They enable users to monitor performance, uncover trends, and make informed decisions by visualizing complex datasets through charts, tables, and key performance indicators (KPIs).","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Dashboards"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Donut chart widget","title":"Donut chart widget","description":"Configuring Donut chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/donut-chart-widget-configuration-settings"},{"id":"BI Analytics/Drill Down/Drill Down Journey","title":"Drill Down Journey","description":"What is Drill Down Journey?","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/Drill Down Journey"},{"id":"BI Analytics/Drill Down/Drill Down - Widget","title":"Drill Down Widget","description":"Administrators can now predefine specific analytical journeys for end-users via drill down. Instead of navigating through complex and unstructured data, users can now follow curated pathways to gain deeper insights. To do this, you must create and save related widgets as drafts. These drafts, which can include any combination of visualizations and settings, represent the steps a user will take when exploring data. When a user clicks on a data point within a widget on the dashboard, they are guided through the predefined draft widgets.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/Drill Down - Widget"},{"id":"BI Analytics/Drill Down/Drill Down-ad hoc","title":"Drill Down- Ad Hoc","description":"What is Ad-Hoc Drill-Down?","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/Drill Down-ad hoc"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Funnel chart widget","title":"Funnel chart widget","description":"Configuring Funnel chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/funnel-chart-widget-configuration-settings"},{"id":"BI Analytics/Widgets/Widget configurations and settings/KPI widget","title":"KPI widget","description":"Configuring KPI widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/kpi-widget-configuration-settings"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Line chart widget","title":"Line chart widget","description":"Configuring Line chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/line-chart-widget-configuration-settings"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Packed bubble chart widget","title":"Packed bubble chart widget","description":"Configuring Packed Bubble chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/packed-bubble-chart-widget-configuration-settings"},{"id":"BI Analytics/Formulas & Parameters/Parameters","title":"Parameters","description":"In DataGOL,Parameters are dynamic input placeholders\u2014such as a number, text, date, or boolean\u2014that replace hardcoded values in formulas or BI Workbooks. They allow users to adjust values on the fly in dashboards or visualizations without editing the actual SQL or underlying dataset.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Formulas & Parameters/Parameters"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Pie chart widget","title":"Pie chart widget","description":"Configuring Pie chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/pie-chart-widget-configuration-settings"},{"id":"BI Analytics/Visualizer/Save widget/Pinning visualization to dashboard","title":"Pinning visualization to dashboard","description":"After you have created a visualization or widget, you can pin it to the dashboards.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Save widget/pin-widget-to-dashboard"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Pivot table widget","title":"Pivot table widget","description":"Configuring Pivot table widget  - configuration and setting","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/pivot-table-widget-configuration-settings"},{"id":"BI Analytics/Visualizer/Save widget/Saving visualization as draft","title":"Saving visualization as draft","description":"Drafting a visualization allows you to save your progress and continue working on it later without losing any changes. This is particularly useful when you are in the middle of creating a complex visualization and need to step away. Saving it as a draft ensures your work is securely stored, so you can pick up right where you left off.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Save widget/save-visualization-as-drafts"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Scatter chart widget","title":"Scatter chart widget","description":"Configuring Scatter chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/scatter-chart-widget-configuration-settings"},{"id":"BI Analytics/Visualizer/Select workbook","title":"Selecting source or workbooks","description":"To begin visualizing data, you must first select a workbook as follows:","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Select workbook"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Table widget","title":"Table widget","description":"Configuring Table widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/table-widget-configuration-settings"},{"id":"BI Analytics/Theming","title":"Theming","description":"Theming of embedded dashboards or third-party sharing dashboards involves customizing their appearance to match the host application\'s look and feel. This process ensures a consistent and seamless user experience, making the embedded dashboard feel like a natural part of the application rather than a separate tool. This is particularly useful for maintaining brand consistency.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/set-theme-third-party-embedded-dashboards"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Tree map chart widget","title":"Tree map chart widget","description":"Configuring Tree map chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/tree-map-chart-widget-configuration-settings"},{"id":"BI Analytics/Visualizer/Select Columns","title":"Understanding columns","description":"Once the workbook is selected, the next step is to identify and add the desired columns to be visualized.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Select Columns"},{"id":"BI Analytics/Visualizer/Understanding Visualizer","title":"Understanding the Visualizer","description":"This topic introduces the user interface (UI) for data visualization. It describes the individual components of the visualizer\'s interface and explains the function of each part. Each of the functions are referenced to the corresponding topics.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Understanding Visualizer"},{"id":"BI Analytics/Visualizer/Details Panel","title":"Viewing the Data Details panel","description":"The Details panel provides in-depth information about the SQL query that powers your current widget. This panel is essential for users who want to understand exactly how their data is being fetched, filtered, and transformed.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Details Panel"},{"id":"BI Analytics/Widgets/Widget Filters","title":"Widget filters","description":"In the Visualizer, you can add filters at the widget level to refine the data displayed in your visualizations.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget Filters"},{"id":"BI Analytics/Widgets/Widget Types","title":"Widget types","description":"Widgets provide a wide range of data visualization options within our business intelligence (BI) tool. By combining different data columns with a variety of widgets, business users can uncover valuable insights. Our system provides visualization suggestions based on your data, helping you understand which visualizations are best suited for your dimensions, metrics, and time-based information.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget Types"}],"unlisted":false}}')}}]);